<?php
declare(strict_types=1);
namespace App\Services\Hrd;use App\Enums\Hrd\{AttendanceStatus,LeaveType};use App\Models\{PersonnelAttendance,PersonnelLeaveRequest,User};use Carbon\CarbonPeriod;use Illuminate\Support\Facades\DB;use Illuminate\Validation\ValidationException;
class LeaveService{public function approve(PersonnelLeaveRequest $leave,User $actor):void{DB::transaction(function()use($leave,$actor){$leave=PersonnelLeaveRequest::lockForUpdate()->findOrFail($leave->id);if($leave->status!=='pending')throw ValidationException::withMessages(['status'=>'Pengajuan sudah diputuskan.']);$leave->update(['status'=>'approved','approved_by'=>$actor->id,'approved_at'=>now()]);$status=match($leave->leave_type){LeaveType::Sick=>AttendanceStatus::Sick,LeaveType::Permission=>AttendanceStatus::Permission,LeaveType::OfficialDuty=>AttendanceStatus::OfficialDuty,default=>AttendanceStatus::Leave};foreach(CarbonPeriod::create($leave->start_date,$leave->end_date) as $date)PersonnelAttendance::updateOrCreate(['personnel_id'=>$leave->personnel_id,'attendance_date'=>$date->format('Y-m-d'),'shift_number'=>$leave->personnel->default_shift_number?:1],['status'=>$status,'method'=>'manual','note'=>'Sinkronisasi pengajuan #'.$leave->id,'created_by'=>$actor->id,'updated_by'=>$actor->id]);activity('hrd')->causedBy($actor)->performedOn($leave)->log('HRD menyetujui izin/cuti.');});}}
